use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let arr = input.as_array().unwrap();
    let mut result = Vec::new();
    for item in arr {
        if let Some(s) = item.as_str() {
            if let Some(first) = result.first() {
                if s == first {
                    result.pop();
                }
            } else {
                result.push(s.to_string());
            }
        }
    }
    Value::Array(result)
}
